                    'قبل از هر گونه گودبرداری و حفاری در مورد وجود و عدم وجود کابل‌های زیرزمینی اطمینان حاصل کنید',
                    'سیم کشی های موقت و دلیم و نصب تجهیزات برقی با رعایت مقررات مربوطه صورت گرفته است',
