                    'کمک‌های اولیه متناسب با نوع کار و تعداد کارگران تهیه و در جای مناسب نگهداری و در دسترس می‌باشند',
                    'افراد در رابطه با استفاده از وسایل کمک‌های اولیه آموزش لازم را دیده اند',
