                    'فضای سرپوشیده کافی برای اقامت و استراحت موقت کارگرانی که به دلیل شرایط کار مجبور به اقامت در کارگاه هستند فراهم شده است',
                    'نور و روشنایی طبیعی و مصنوعی کافی م تناسب ثابت و قابل حمل در محل های کار، عبور و مرور، غذاخوری، اقامت و استراحت کارگران فراهم شده است',
                    'محل مناسب کافی برای اقامت و استراحت موقت کارگرانی که به دلیل شاریط کار مجبور به اقامت در کارگاه هستند فراهم شده است',
                    'آیا محل کار، اقامت، استراحت و غذا خوری کارگران، از هوای کافی و سالم به طور طبیعی و یا تهویه مصنوعی برخوردار می‌باشند',
                    'کارگران، افراد خویش فرما و سایر کسانی که در کارگاه ساختمانی فعالیت و یا به دلیلی وارد می‌شوند متناسب با نوع کار از وسایل حفاظت فردی استفاده می‌کنند',
