                    'در تهیه و کاربرد وسایل حفاظت فردی ضوابط مندرج در ایین نامه وسایل حفاظت افرادی لحاظ گردیده است.',
                    'در صورتی که احتمال وارد امدن صدماتی به سر افراد در اثر سقوط فرد از ارتفاع یا سقوط، تجهیزات و مصالح و یا برخورد موانع وجود دارد از کلاه ایمنی استاندارد استفاده می‌شود',
                    'برای انجام دادم کار در ارتفاع که امکان تعبیه سازی حفاظتی برای جلوگیری از سقوط کارگران وجود ندارد از کمربند ایمنی و طناب مهار از نوع استاندارد استفاده می‌شود.',
                    'قبل از هر بار استفاده از کمذبند ایمنی و طناب مهار کلیه قسمت ها و اجزای آن‌ها مورد بازدید و کنترل شخص ذی‌صلاح قرار می‌گیرد.',
