                    'در صورتی که به لحاظ فنی امکان تهویه محیط الوده به گردو غبار، گازها و بخارهای شیمیایی و زیان آور وجود ندارد آیا کارگران از ماسک تنفسی استاندارد مناسب استفاده می‌کنند',
                    'کارگرانی که هنگام کار پایشان در معرض خطر برخورد با اجسام داغ و برنده و یا سقوط اجسام و همچنین خطر برق گرفتگی قرار دارند از کفش و پوتین استاندارد متناسب با نوع کار و خطرهای مربوطه استفاده می‌کنند',
                    'کارگران برق کار و همچنین کارگرانی که به اشیا داغ و برنده و همچنین مواد خورنده و تحریک کننده پوست سر و کار دارند از دستکش حفاظتی استاندارد متناسب با نوع کار و خطرهای مربوطه استفاده می‌کنند',
                    'کارگران در محل های کاراز لباس تمیز و متناسب با نوع کار و خطرهایی که کارگر با آن مواجه است استفاده می‌کنند',
                    'برای جلوگیری از سقوط افراد در محل‌هایی که ارتفاع سقوط بیش از 120 سانتی‌متر است نرده حفاظتی موقت نصب گردیده است',
                    'در صورت نصب نرده حفاظتی موقت ارتفاع آن از کف طبقه بین 9 تا 110 سانتی‌متر می‌باشد.',
                    'نرده حفاظتی موقت در فاصله هر 2 متر دارای پایه عمودی می‌باشد.',
