                    'بارگیری وسایل موتوری نقل و انتقال و گودبرداری و جابجایی مصالح با رعایت ظرفیت مجاز آن‌ها صورت می‌گیرد.',
                    'کلیه قسمت‌های داربست توسط شخص ذی‌صلاحطوری طراحی، ساخته و اماده به‌کار شده است که داربست در مقابل چهار برابر بار وارده ایستایی لازم را داشته باشد',
