                    'برای جلوگیری از خطر سقوط کارگران و همچنین پیشگیری از افتادن مصالح و ابزار کار از روی کف جایگاه، طرف باز جایگاه با نرده حفاظتی و پاخورهای مناسب محافظت شده است',
