                    'راه پله‌های موقت با طول و حداقل یک متر، عرض حداقل 25 سانتی‌متر و ارتفاع حداکثر 22 سانتی‌متر و همچنین اختالف سطح بین دو پاگرد حداکثر 4 متر ساخته شده است.',
